"""College-Level and Simplified wordings for Module I quiz questions. Collections 05 and 06."""
V = {}
def v(qid, college, simple):
    V[qid] = (college, simple)

# Collection 05 · Attention · Part 2
v(63, ('The naturalistic driving study is quasi-experimental. What limit does that place on its conclusions?', 'Drivers were not randomly assigned to conditions, so the results are associations.', 'The drivers knew which crashes were going to be studied, so they drove carefully.', 'Every crash was planned by the researchers, so none of them was natural.', 'The cameras could not record where drivers looked, so gaze is unknown.'),
      ('Was an experimenter present in the naturalistic driving study?', 'No. Drivers drove with no experimenter present.', 'No. Drivers were watched from a second car.', 'Yes. An experimenter sat in every car.', 'Yes, but only during crashes.'))
v(64, ('In the 100-car study, what is a conflict called when it needs a rapid, severe evasive maneuver and there is no contact?', 'A near crash.', 'A crash.', 'An incident.', 'A baseline period.'),
      ('What is a near crash?', 'A conflict that needs a rapid, severe evasive maneuver.', 'Contact with another vehicle.', 'A period of normal driving.', 'A small maneuver of little severity.'))
v(65, ('In the 100-car study, what proportion of crashes involved inattention within three seconds before the conflict?', '80 percent.', '65 percent.', '18 percent.', '39 percent.'),
      ('What was a primary contributing factor in many crashes in the 100-car study?', 'Inattention to the forward roadway.', 'Bad weather.', 'Speeding only.', 'Mechanical failure.'))
v(66, ('In Strayer and Johnston (2001), a hands-free phone also impaired simulated driving. Why?', 'The conversation divides attention.', 'Holding a phone is the only source of distraction.', 'The phone blocks the driver’s view.', 'Practice removes all limits on divided attention.'),
      ('Did a hands-free phone remove the driving impairment in Strayer and Johnston (2001)?', 'No. The same pattern occurred with a hands-free phone.', 'No. Hands-free driving was much worse than hand-held.', 'Yes. Hands-free driving was normal.', 'Yes, but only for braking.'))
v(67, ('Participants judging the arms of a cross did not see a square that was added to the display. What is this called?', 'Inattentional blindness.', 'Change blindness.', 'An illusory conjunction.', 'Attentional capture.'),
      ('What is inattentional blindness?', 'Failing to perceive an unattended stimulus, even when looking toward it.', 'Failing to notice a difference between two versions of a picture.', 'Combining features from different objects.', 'Being unable to move the eyes.'))
v(68, ('A viewer does not notice a difference between two versions of a picture. What is this called?', 'Change blindness.', 'Inattentional blindness.', 'Binding.', 'Attentional capture.'),
      ('What is change blindness?', 'Failing to notice a difference between two versions of a picture.', 'Failing to see an unexpected object while attending elsewhere.', 'Seeing features in the wrong combination.', 'Losing vision on one side.'))
v(69, ('What happens in the preattentive stage of feature integration theory?', 'The object is analyzed into separate features.', 'The features are combined by focused attention.', 'The meaning of the object is retrieved.', 'A failed interpretation is repaired.'),
      ('Does the preattentive stage need attention?', 'No. It is automatic.', 'No. It happens only during sleep.', 'Yes. It needs focused attention.', 'Yes, but only for color.'))
v(70, ('A display has a red triangle and a yellow circle, and the participant reports a red circle. What is this error?', 'An illusory conjunction.', 'A report of a feature that was not shown.', 'A correct binding.', 'Inattentional blindness.'),
      ('What is an illusory conjunction?', 'A combination of features from different objects.', 'A feature that was never in the display.', 'A missed change between two pictures.', 'A slow response to a cued location.'))
v(71, ('Which of these does feature integration theory NOT predict?', 'Observers will report features that were never present.', 'Unattended objects may be bound incorrectly.', 'Illusory conjunctions may occur.', 'Focused attention improves the pairing of features.'),
      ('Which stage of feature integration theory combines the features?', 'The focused attention stage.', 'The preattentive stage.', 'The sensory memory stage.', 'The detector stage.'))
v(72, ('In Treisman and Schmidt (1982), on what proportion of trials did participants report illusory conjunctions of the colored shapes?', '18 percent.', '80 percent.', '65 percent.', '100 percent.'),
      ('In Treisman and Schmidt (1982), how long was the display flashed?', 'One fifth of a second.', 'Five seconds.', 'One minute.', 'Two seconds.'))
v(73, ('Patient R.M., who had Balint’s syndrome, reported many illusory conjunctions. What does this fit with?', 'Difficulty focusing attention on single objects, which is needed to bind features.', 'A loss of the ability to register any individual feature of an object.', 'An attentional capacity that is larger than normal, which adds extra features.', 'A problem in the preattentive stage, which removes features from objects.'),
      ('What could patient R.M. not do?', 'Focus attention on individual objects.', 'Name any colors.', 'Understand spoken words.', 'Remember new facts.'))
v(74, ('In Treisman and Schmidt (1982), what happened when participants ignored the black numbers and focused on the objects?', 'They paired shapes and colors correctly.', 'They made more illusory conjunctions.', 'They could not see the objects.', 'They reported features that were not shown.'),
      ('Does top-down processing help binding?', 'Yes. Knowing what to expect helps perception become accurate.', 'No. Binding is bottom-up only.', 'No. Knowledge makes binding worse.', 'Only for letters.'))
v(75, ('What does a topographic map in the visual cortex preserve?', 'The spatial relationships between positions in the visual field.', 'The colors of the objects in the visual field.', 'An exact photograph of the scene.', 'The order in which objects were attended.'),
      ('In a topographic map, where do neighboring points of a stimulus cause activity?', 'At neighboring points on the cortex.', 'At opposite ends of the cortex.', 'In the retina only.', 'At random points on the cortex.'))
v(76, ('Datta and DeYoe’s classifiers predicted the attended location with 100 percent accuracy. How should this be read?', 'As accuracy within the task they were trained on.', 'As access to all of a person’s thoughts.', 'As proof that fMRI makes no errors.', 'As a result for any person and any task.'),
      ('What did Datta and DeYoe’s classifiers predict?', 'Where a person was paying attention.', 'What a person was saying.', 'Which object a person would choose.', 'What a person remembered.'))
v(77, ('In O’Craven and colleagues (1999), a face and a house overlapped. Which activity increased when the house was attended?', 'Activity in the parahippocampal gyrus.', 'Activity in the fusiform face area.', 'Activity in Broca’s area.', 'Activity in the retina.'),
      ('In O’Craven and colleagues (1999), which area became more active when participants attended to the face?', 'The fusiform face area.', 'The parahippocampal gyrus.', 'Wernicke’s area.', 'The optic nerve.'))
v(156, ('Which statements about the physiology of attention are true? I. Attention enhances neural responding. II. Attentional processing is distributed across many areas. III. A topographic map links visual positions to cortical positions.', 'I, II and III.', 'I only.', 'I and II only.', 'II and III only.'),
       ('Does attention change how strongly neurons respond?', 'Yes. Attention enhances neural responding.', 'No. Attention has no effect on neurons.', 'It lowers every response.', 'Only in the retina.'))
v(193, ('Why did the 100-car study use drivers’ own cars on public roads?', 'To record behavior in a naturalistic setting.', 'To cause crashes under controlled conditions.', 'To give every driver the same distraction.', 'To remove every possible confound.'),
       ('How long did drivers take part in the 100-car study?', 'Up to 13 months.', 'One day.', 'One week.', 'Up to 3 months.'))
v(194, ('Which pair of figures from the 100-car study is correct?', '80 percent of crashes and 65 percent of near crashes involved inattention.', '65 percent of crashes and 80 percent of near crashes involved inattention.', '18 percent of crashes and 39 percent of near crashes involved inattention.', '10 percent of crashes and 100 percent of near crashes involved inattention.'),
       ('In the 100-car study, what proportion of near crashes involved inattention?', '65 percent.', '80 percent.', '10 percent.', '93 percent.'))
v(195, ('Which result goes against the idea that phones distract only because one hand is busy?', 'Drivers on hands-free phones also missed more red lights and braked later.', 'A hand-held phone occupies one hand.', 'Drivers can see the road without a phone.', 'Drivers sometimes turn the wheel with one hand.'),
       ('About how much higher was accident risk during cell phone use?', 'About four times higher.', 'About twice as high.', 'About ten times higher.', 'No higher.'))
v(196, ('Why is looking toward an unexpected stimulus not enough to see it?', 'Attention can be engaged by another task.', 'The retina cannot register it.', 'Fixating removes information.', 'The stimulus has to be a word.'),
       ('In Cartwright-Finch and Lavie (2007), what proportion of participants saw the added square?', '10 percent.', '90 percent.', '50 percent.', '100 percent.'))
v(197, ('What is the binding problem?', 'How separately processed features are combined into one object.', 'How words are counted in a corpus.', 'How new information interferes with old information.', 'How attention moves without the eyes.'),
       ('What is binding?', 'Combining features such as color, form and motion into one object.', 'Separating an object into features.', 'Remembering a list in order.', 'Moving attention to a cue.'))
v(198, ('In Treisman and Schmidt (1982), why were participants asked to report the black numbers first?', 'To draw attention away from the shapes.', 'To make sure every shape got full attention.', 'To keep the display on the screen longer.', 'To make the shapes easier to remember.'),
       ('In Treisman and Schmidt (1982), what followed the display?', 'A random dot mask.', 'A second display of shapes.', 'A loud tone.', 'A blank screen for one minute.'))
v(199, ('What is the difference between a binding error and a feature error?', 'A binding error combines features that were shown. A feature error reports a feature that was not shown.', 'A binding error is any wrong answer. A feature error is any right answer.', 'A binding error is about color. A feature error is about shape.', 'A binding error happens with words. A feature error happens with sentences.'),
       ('Participants reported digits first and then letters and their colors. Which error was more frequent?', 'Mixing up letters and colors.', 'Reporting a letter or color that was not shown.', 'They were equally frequent.', 'Neither error occurred.'))
v(200, ('Attending to an expected direction of motion increased fMRI activity in a number of brain areas. What does this support?', 'Attention is distributed across the cortex.', 'One area carries out all of attention.', 'Attention has no physiological basis.', 'Attention changes activity only in the retina.'),
       ('Which method detected cortical activity while participants attended to a direction of motion?', 'fMRI.', 'An eye tracker.', 'A reaction time apparatus.', 'A moving window.'))
v(201, ('Why did O’Craven and colleagues (1999) show a face and a house overlapping?', 'Both stay in the display while the attended one changes.', 'The face disappears when the house is attended.', 'The house is easier to see than the face.', 'It measures only the speed of a response.'),
       ('In O’Craven and colleagues (1999), were the face and the house both present?', 'Yes. They overlapped in the same display.', 'No. Only the face was shown.', 'No. Only the house was shown.', 'No. They were shown on different days.'))

# Collection 06 · Language · Part 1
v(78, ('What is the shortest segment of speech that changes the meaning of a word when it is changed?', 'A phoneme.', 'A morpheme.', 'A syllable.', 'A letter.'),
      ('How many phonemes does the word “bit” have?', 'Three.', 'One.', 'Two.', 'Four.'))
v(79, ('How many morphemes are in “bedrooms”?', 'Three.', 'One.', 'Two.', 'Eight.'),
      ('How many morphemes are in “table”?', 'One.', 'Two.', 'Three.', 'Five.'))
